def flipLights(n: int, m: int) -> int:
    # Only first 3 bulbs affect the outcome due to operation overlaps
    if m == 0:
        return 1
    if n == 1:
        return 2
    if n == 2:
        if m == 1:
            return 3
        return 4
    # n >= 3
    if m == 1:
        return 4
    if m == 2:
        return 7
    return 8
